Body:
Fix GPT-5.6 Sol + opencode: Plugin Custom for gpt 5 

Issue: Azure GPT-5 (5.4, 5.6) Error: "max_tokens" is not supported, use "max_completion_tokens" instead

Solution : Create plugin custom opencode + config model

1. Create Plugin Fix
Save on ~/.config/opencode/fix-gpt5-tokens.plugin.ts:

```
import type { Plugin } from "@opencode-ai/plugin"

export default (async ({ client }) => {
  return {
    config: (cfg) => {
      const azureProvider = cfg.provider?.["gpt-5_6-sol"]?.options
      if (azureProvider) {
        const originalFetch = azureProvider.fetch

        azureProvider.fetch = async (url: any, options: any) => {
          if (options?.body) {
            let body: any
            if (typeof options.body === "string") {
              body = JSON.parse(options.body)
            } else {
              body = options.body
            }
            if (body.max_tokens !== undefined) {
              body.max_completion_tokens = body.max_tokens
              delete body.max_tokens
              options.body = JSON.stringify(body)
            }
          }
          return originalFetch
            ? originalFetch(url, options)
            : fetch(url, options)
        }
      }
    },
  }
}) satisfies Plugin
```


2. Register on opencode.json
```
{
  "$schema": "https://opencode.ai/config.json",
  "disabled_providers": [],
  "plugin": [
    "~/.config/opencode/fix-gpt5-tokens.plugin.ts"
  ],
  "provider": {
    "gpt-5_6-sol": {
      "name": "gpt-5.6-sol",
      "npm": "@ai-sdk/openai-compatible",
      "options": {
        "baseURL": "https://<XXXX>.services.ai.azure.com/openai/v1"
      },
      "models": {
        "gpt-5.6-sol": {
          "name": "gpt-5.6-sol",
          "options": {
            "reasoningEffort": "none"
          }
        }
      }
    }
  }
}
```

3. Test
npx opencode-ai run "test" --model gpt-5_6-sol/gpt-5.6-sol
